/**
 * Trouve l'élément contenant le compteur de résultats dans la section _lower-search-nav-reflow
 * Utilisé pour insérer le bouton TotLeads juste avant cet élément
 * @param {Element} container - Le conteneur _lower-search-nav-reflow
 * @returns {Element|null} - L'élément du compteur de résultats ou null
 */
function findResultsCountElement(container) {
  if (!container) return null;

  try {
    // Stratégie 1: Chercher parmi les enfants directs du container celui qui contient "results"
    // C'est le dernier div enfant direct qui contient le compteur
    const directChildren = container.children;
    for (let i = directChildren.length - 1; i >= 0; i--) {
      const child = directChildren[i];
      const text = child.textContent.trim().toLowerCase();
      // Chercher un élément contenant un nombre suivi de "result" ou "résultat"
      if (/\d+\s*(result|résultat)/i.test(text)) {
        return child;
      }
    }

    // Stratégie 2: Chercher par la classe mlA (margin-left: auto) parmi les enfants directs
    for (const child of directChildren) {
      if (child.classList && child.classList.contains('mlA')) {
        return child;
      }
      // Aussi vérifier si la classe contient mlA (pour les classes dynamiques)
      if (child.className && child.className.includes('mlA')) {
        return child;
      }
    }

    // Stratégie 3: Chercher le div avec classes t-14 et mlA
    const resultsDiv = container.querySelector('div.t-14[class*="mlA"]');
    if (resultsDiv) {
      return resultsDiv;
    }

    // Stratégie 4: Chercher un div enfant direct contenant un span avec "results"
    for (const child of directChildren) {
      if (child.tagName === 'DIV') {
        const span = child.querySelector('span');
        if (span) {
          const text = span.textContent.toLowerCase();
          if (text.includes('result') || text.includes('résultat')) {
            return child;
          }
        }
      }
    }

    // Stratégie 5: Prendre le dernier enfant direct s'il est un div (souvent le compteur)
    const lastChild = directChildren[directChildren.length - 1];
    if (lastChild && lastChild.tagName === 'DIV') {
      return lastChild;
    }

    return null;
  } catch (error) {
    return null;
  }
}

/**
 * Trouve le conteneur des boutons LinkedIn Sales Navigator
 * Cible la section _lower-search-nav-reflow qui contient les actions en masse
 * @returns {Promise<Element|null>} - Conteneur trouvé ou null
 */
async function findButtonContainer() {
  const config = window.TotleadsConfig;
  try {
    // Stratégie 1: Chercher par la classe CSS spécifique _lower-search-nav-reflow
    // Cette section contient le checkbox "Select all", les boutons d'action et le compteur de résultats
    const navReflowContainer = document.querySelector('.flex.align-items-center.full-width[class*="_lower-search-nav-reflow"]');
    if (navReflowContainer) {
      return navReflowContainer;
    }

    // Stratégie 2: Chercher par l'icône SVG "bulleted-list-icon" (unique au bouton Save to list)
    const bulletedListIcon = document.querySelector('li-icon[type="bulleted-list-icon"]');
    if (bulletedListIcon) {
      const container = bulletedListIcon.closest('.flex.align-items-center.full-width');
      if (container) return container;
    }

    // Stratégie 3: Chercher par l'attribut data-x--save-menu-trigger
    const saveMenuButton = document.querySelector('button[data-x--save-menu-trigger]');
    if (saveMenuButton) {
      const container = saveMenuButton.closest('.flex.align-items-center.full-width');
      if (container) return container;
    }

    // Stratégie 4: Chercher par la classe _bulk-action-control (utilisée par tous les boutons d'action en masse)
    const bulkActionButton = document.querySelector('button[class*="_bulk-action-control"]');
    if (bulkActionButton) {
      const container = bulkActionButton.closest('.flex.align-items-center.full-width');
      if (container) return container;
    }

    // Stratégie 5: Chercher par le checkbox multi-selector
    const multiSelectorCheckbox = document.querySelector('input[id^="multi-selector-checkbox-"]');
    if (multiSelectorCheckbox) {
      const container = multiSelectorCheckbox.closest('.flex.align-items-center.full-width');
      if (container) return container;
    }

    // Stratégie 6 (Fallback): Chercher un conteneur avec checkbox + plusieurs boutons disabled
    const flexContainers = document.querySelectorAll('.flex.align-items-center.full-width');
    for (const container of flexContainers) {
      const hasCheckbox = container.querySelector('input[type="checkbox"]');
      const disabledButtons = container.querySelectorAll('button[disabled]');
      if (hasCheckbox && disabledButtons.length >= 2) {
        return container;
      }
    }

    return null;
  } catch (error) {
    return null;
  }
}

/**
 * Rend le bouton d'export responsive selon la largeur de la fenêtre
 * Adapte le texte et la taille du bouton
 */
function makeButtonResponsive() {
  const config = window.TotleadsConfig;
  const i18n = window.TotleadsI18n;

  const button = document.getElementById(config.selectors.EXPORT_BUTTON_ID);
  if (!button) return;

  const label = button.querySelector('[data-totleads-role="export-button-label"]');
  if (!label) return;

  const leadsCount = button.dataset.leadsCount ? parseInt(button.dataset.leadsCount) : 0;
  const windowWidth = window.innerWidth;

  // Gérer l'affichage du bouton "Personas" adjacent
  // Chercher le bouton Personas dans le même conteneur que le bouton d'export
  const buttonContainer = button.parentElement;
  let personasButton = null;

  if (buttonContainer) {
    // Chercher le bouton qui contient le texte "Personas" ou ses variantes
    const allButtons = buttonContainer.querySelectorAll('button');
    for (const btn of allButtons) {
      const btnText = btn.textContent.trim().toLowerCase();
      // Vérifier si c'est le bouton Personas (peut être en différentes langues)
      if (btnText.includes('personas') && btn.id !== config.selectors.EXPORT_BUTTON_ID) {
        personasButton = btn;
        break;
      }
    }
  }

  // Très petite fenêtre (< 600px) : Icône uniquement
  if (windowWidth < 600) {
    label.textContent = '';
    // button.style.setProperty('min-width', '40px', 'important');
    // button.style.setProperty('padding', '8px', 'important');
    button.style.setProperty('margin-left', '4px', 'important');

    // Masquer le bouton Personas
    if (personasButton) {
      personasButton.style.setProperty('display', 'none', 'important');
    }
  }
  // Petite fenêtre (600px - 1200px) : Texte court
  else if (windowWidth < 1200) {
    label.textContent = i18n.t('extraction.exportButtonShort') || 'Export';
    // button.style.setProperty('min-width', '100px', 'important');
    // button.style.setProperty('padding', '10px 15px', 'important');
    button.style.setProperty('margin-left', '8px', 'important');

    // Masquer le bouton Personas
    if (personasButton) {
      personasButton.style.setProperty('display', 'none', 'important');
    }
  }
  // Fenêtre normale (> 1200px) : Texte complet avec nombre
  else {
    label.textContent = i18n.t('extraction.exportButtonWithCount', { count: leadsCount });
    // button.style.setProperty('min-width', '200px', 'important');
    // button.style.setProperty('padding', '10px 20px', 'important');
    button.style.setProperty('margin-left', '12px', 'important');

    // Afficher le bouton Personas
    if (personasButton) {
      personasButton.style.removeProperty('display');
    }
  }
}

/**
 * Initialise l'observateur de redimensionnement pour le bouton responsive
 */
function initResponsiveButtonObserver() {
  // Éviter de créer plusieurs observateurs
  if (window.__totleads_responsiveObserverInitialized) {
    makeButtonResponsive(); // Appliquer quand même la responsivité
    return;
  }

  // Debounce pour éviter trop d'appels pendant le redimensionnement
  let resizeTimeout;
  const debouncedResize = () => {
    if (resizeTimeout) clearTimeout(resizeTimeout);
    resizeTimeout = setTimeout(() => {
      makeButtonResponsive();
    }, 100);
  };

  // Créer un ResizeObserver pour détecter les changements de taille
  if (typeof ResizeObserver !== 'undefined') {
    const resizeObserver = new ResizeObserver(debouncedResize);
    resizeObserver.observe(document.body);
  } else {
    // Fallback: utiliser window.resize
    window.addEventListener('resize', debouncedResize);
  }

  // Marquer comme initialisé
  window.__totleads_responsiveObserverInitialized = true;

  // Appliquer immédiatement la responsivité
  makeButtonResponsive();
}

// Exposer les fonctions globalement
if (typeof window !== 'undefined') {
  window.TotleadsDOMHelpers = {
    waitForElement,
    isOnSalesNavigator,
    isOnSalesNavigatorCompanySearch,
    isOnLastSearchPage,
    getCurrentPageNumber,
    hasSearchFiltersOrResults,
    createStyledButton,
    findButtonContainer,
    findResultsCountElement,
    makeButtonResponsive,
    initResponsiveButtonObserver,
  };
}
